PROGRAM ST010_STOPPGRIND
VAR
    steg           : INT := 0;
    trigPec        : R_TRIG;
    tmrUppehall    : TON;
    tmrAndlage     : TON;
    tmrOppen       : TON;
    xUppehall      : BOOL := FALSE;
    xVantarAndlage : BOOL := FALSE;
    xBurkenUt      : BOOL := FALSE;
    xFartOK        : BOOL := FALSE;
    xLagesfel      : BOOL := FALSE;
    xDriftsklar    : BOOL := FALSE;
END_VAR

(* EMG_OK och AIR_OK lases bara. Den har logiken bar ingen sakerhetsfunktion;
   den ar forreglad AV nodstoppskretsen. *)

(* Flanken hamtas i VARJE scan, aven medan grinden ar i rorelse. Singuleringen
   ar en flankrakning: en burk per stigande flank pa fotocellen. Lases nivan i
   stallet star grinden kvar oppen sa lange stralen ar bruten, och tva burkar
   gar ut pa en flank. *)
trigPec(CLK := ST010_PEC_PART);

(* Arbetsfonstret for bandhastigheten. Under 0,20 m/s har bandet inte fart nog
   att fora bort burken nar grinden oppnar; over 0,80 m/s racker inte
   uppehallet 0,40 s mot bandets efterslapning. *)
xFartOK := (ST010_CNV_SPD >= 0.20) AND (ST010_CNV_SPD <= 0.80);

(* Grindens slagtid ar 0,12 s. Bekraftar inte andlagesgivaren oppet lage inom
   1,0 s, alltsa atta slagtider, har givaren eller grinden lossnat och
   styrningen far inte anta att grinden ar oppen. *)
xVantarAndlage := (steg = 2);
tmrAndlage(IN := xVantarAndlage, PT := T#1s);
IF tmrAndlage.Q THEN
    xLagesfel := TRUE;
END_IF;

xDriftsklar := EMG_OK AND AIR_OK AND xFartOK AND NOT xLagesfel;

(* Uppehallet raknas fran fotocellens flank. Burken behover 120/500 = 0,24 s
   pa sig att na fram till grinden; vid 0,40 s har den statt still mot grinden
   och glider inte vidare pa efterslapningen. *)
xUppehall := (steg = 1);
tmrUppehall(IN := xUppehall, PT := T#400ms);

(* Grinden halls oppen tills burken hunnit ut. En burk pa 99 mm passerar
   grinden pa 99/500 = 0,198 s vid 0,5 m/s; 0,30 s racker med marginal och
   ligger under taket 0,50 s efter oppning. *)
xBurkenUt := (steg = 3);
tmrOppen(IN := xBurkenUt, PT := T#300ms);

IF NOT xDriftsklar THEN
    ST010_CNV_RUN := FALSE;
    ST010_STP_OPEN := FALSE;
    steg := 0;
ELSE
    ST010_CNV_RUN := TRUE;
    CASE steg OF
        0:
            ST010_STP_OPEN := FALSE;
            IF trigPec.Q THEN
                steg := 1;
            END_IF;
        1:
            IF tmrUppehall.Q THEN
                ST010_STP_OPEN := TRUE;
                steg := 2;
            END_IF;
        2:
            IF ST010_STP_OPENED THEN
                steg := 3;
            END_IF;
        3:
            IF tmrOppen.Q THEN
                ST010_STP_OPEN := FALSE;
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
END_IF;
END_PROGRAM

